/**
 * Parity with the JavaScript implementation that predates the migration to
 * TypeScript.
 *
 * The legacy-render.json fixture was generated by running the old code
 * (assets/js/bibleUtils.js and bibleManager.js) on the published Bibles, with
 * dozens of references and combinations of display options. Intentional
 * behavior changes must update the fixture explicitly.
 *
 * The cases of por_ara were removed when the Bible was replaced by the bible.com one (which has
 * section titles the old text lacked): the legacy code no longer exists to regenerate them.
 */
import { describe, expect, it } from 'vitest';
import type { DisplayOptions } from '../../src/core/passage';
import { renderInputReference } from '../../src/core/render';
import { formatVerseRanges, parseReference } from '../../src/core/reference';
import { loadBible, readFixture } from '../helpers';

interface LegacyFixture {
    instructions: string;
    optionSets: DisplayOptions[];
    cases: { bible: string | null; inputReference: string; options: number; error: boolean; html: string }[];
    parse: { inputReference: string; parsed: unknown }[];
    effective: { verses: number[]; output: string }[];
}

const fixture = JSON.parse(readFixture('legacy-render.json')) as LegacyFixture;

/**
 * The legacy code wrote the single quotes it put in place of double quotes
 * unescaped; now every single quote in the text is escaped (same display).
 */
const sameDisplay = (html: string) => html.replaceAll('&#39;', "'");

const comparable = (result: { error: boolean; html: string }) => ({ error: result.error, html: sameDisplay(result.html) });

describe('parity with the legacy implementation', () => {
    it.each(fixture.parse)('parseReference($inputReference)', ({ inputReference, parsed }) => {
        expect(parseReference(inputReference)).toEqual(parsed);
    });

    it.each(fixture.effective)('formatVerseRanges($verses)', ({ verses, output }) => {
        expect(formatVerseRanges(verses)).toBe(output);
    });

    const withBible = fixture.cases.filter((c) => c.bible !== null);
    it(`renders ${withBible.length} cases identical to the legacy output`, () => {
        for (const c of withBible) {
            const options = fixture.optionSets[c.options];
            if (!options) throw new Error(`option set ${c.options} does not exist`);
            const result = renderInputReference(c.inputReference, loadBible(c.bible ?? ''), { ...options }, fixture.instructions);
            expect(comparable(result), `${c.bible} | ${c.inputReference} | options ${c.options}`).toEqual(comparable(c));
        }
    });

    it('with no Bible loaded', () => {
        for (const c of fixture.cases.filter((c) => c.bible === null)) {
            const options = fixture.optionSets[0];
            if (!options) throw new Error('option set 0 does not exist');
            expect(comparable(renderInputReference(c.inputReference, null, options, 'X'))).toEqual(comparable(c));
        }
    });
});
